const {chromium}=require('playwright'),fs=require('fs'),path=require('path'),assert=require('node:assert/strict');
(async()=>{const b=await chromium.launch({headless:true});try{
 const p=await b.newPage({viewport:{width:390,height:844}});await p.route('**/*',r=>r.abort());const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.setContent('<main><h1 id="label"></h1><div id="accounts"></div><div id="connect"></div></main>');
 const root=path.join(__dirname,'../web');for(const f of ['00-core','05-primitives','30-calendar'])await p.addStyleTag({content:fs.readFileSync(path.join(root,'css/'+f+'.css'),'utf8')});
 await p.evaluate(()=>{window.el=(tag,cls,text)=>{const e=document.createElement(tag);e.className=cls||'';e.textContent=text||'';return e};window.state={cal:{year:2026,month:8}};window.pad=n=>String(n).padStart(2,'0');window.els={calMonthLabel:document.getElementById('label'),calAccounts:document.getElementById('accounts'),calConnect:document.getElementById('connect')};window.renderCalAccounts=()=>{};window.renderMonth=(cells,events)=>window.rendered=events;window.mode='partial';window.fetch=async url=>({ok:mode!=='failed'||url.endsWith('/status'),json:async()=>url.endsWith('/status')?{accounts:['one','two'],hasCreds:true,accountStatuses:[{needsReauth:true}]}:{events:[{id:'same',key:'source-one',title:'Available event'}],partial:mode==='partial'}});});
 const source=fs.readFileSync(path.join(root,'js/30-calendar.js'),'utf8');await p.addScriptTag({content:source.slice(0,source.indexOf('// Show the accounts list'))});await p.addScriptTag({content:source.slice(source.indexOf('function renderCalError('),source.indexOf('const MAX_PER_DAY'))});
 await p.evaluate(()=>loadCalendar());await p.getByText(/Some calendars could not be fully read/).waitFor();assert.equal(await p.evaluate(()=>rendered[0].key),'source-one');
 for(const width of [320,390,1440]){await p.setViewportSize({width,height:844});assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);}
 await p.setViewportSize({width:390,height:844});await p.screenshot({path:'/tmp/manifest-calendar-partial.png'});
 await p.evaluate(()=>{mode='complete';return loadCalendar()});assert.equal(await p.locator('#calErrBanner').count(),0);
 await p.evaluate(()=>renderCalError(true,[],false));await p.getByText(/Couldn't load your events/).waitFor();assert.deepEqual(errors,[]);console.log('PASS: incomplete calendar read is visible, available events remain, complete recovery clears warning.');
}finally{await b.close()}})().catch(e=>{console.error(e);process.exitCode=1});
